// Helper for localStorage
const getLocal = (key, def = null) => {
  try {
    const val = localStorage.getItem(key);
    return val !== null ? val : def;
  } catch {
    return def;
  }
};
const setLocal = (key, val) => {
  try {
    localStorage.setItem(key, val);
  } catch {}
};
const removeLocal = (key) => {
  try {
    localStorage.removeItem(key);
  } catch {}
};

const defaultBuy = 100;
const defaultSell = 105;
const defaultQty = 100;

function BrokerageTab() {
  // --- State ---
  const [currentTab, setCurrentTab] = useState("easy");
  const [investmentType, setInvestmentType] = useState("equity_delivery");
  const [amount, setAmount] = useState(10000);
  const [tradeType, setTradeType] = useState("equity_delivery");
  const [buyPrice, setBuyPrice] = useState(defaultBuy);
  const [sellPrice, setSellPrice] = useState(defaultSell);
  const [quantity, setQuantity] = useState(defaultQty);
  const [savePref, setSavePref] = useState(
    getLocal("zerodha_save_pref", "0") === "1"
  );
  const [savePrefs, setSavePrefs] = useState(() => {
    try {
      return JSON.parse(getLocal("zerodha_save_prefs", "[]"));
    } catch {
      return [];
    }
  });
  const [savePrefStatus, setSavePrefStatus] = useState("");
  const [showSavePrefTooltip, setShowSavePrefTooltip] = useState(false);
  const [showSavePrefOptions, setShowSavePrefOptions] = useState(false);
  const [showEasyBreakdown, setShowEasyBreakdown] = useState(false);
  const [showAccurateBreakdown, setShowAccurateBreakdown] = useState(false);

  // --- Effects: Restore preferences on mount ---
  useEffect(() => {
    if (savePref) {
      if (savePrefs.includes("tab")) {
        const rememberedTab = getLocal("zerodha_tab");
        if (rememberedTab) setCurrentTab(rememberedTab);
      }
      if (savePrefs.includes("tradeType")) {
        const rememberedType = getLocal("zerodha_trade_type");
        if (rememberedType) setTradeType(rememberedType);
      }
      if (savePrefs.includes("buy")) {
        const rememberedBuy = getLocal("zerodha_buy");
        if (rememberedBuy) setBuyPrice(Number(rememberedBuy));
      }
      if (savePrefs.includes("sell")) {
        const rememberedSell = getLocal("zerodha_sell");
        if (rememberedSell) setSellPrice(Number(rememberedSell));
      }
      if (savePrefs.includes("qty")) {
        const rememberedQty = getLocal("zerodha_qty");
        if (rememberedQty) setQuantity(Number(rememberedQty));
      }
    }
  }, []);

  // --- Save preferences when toggled or changed ---
  useEffect(() => {
    setLocal("zerodha_save_pref", savePref ? "1" : "0");
    if (!savePref) {
      removeLocal("zerodha_save_prefs");
      removeLocal("zerodha_tab");
      removeLocal("zerodha_trade_type");
      removeLocal("zerodha_buy");
      removeLocal("zerodha_sell");
      removeLocal("zerodha_qty");
    } else {
      setLocal("zerodha_save_prefs", JSON.stringify(savePrefs));
      if (savePrefs.includes("tab")) setLocal("zerodha_tab", currentTab);
      else removeLocal("zerodha_tab");
      if (savePrefs.includes("tradeType"))
        setLocal("zerodha_trade_type", tradeType);
      else removeLocal("zerodha_trade_type");
      if (savePrefs.includes("buy")) setLocal("zerodha_buy", buyPrice);
      else removeLocal("zerodha_buy");
      if (savePrefs.includes("sell")) setLocal("zerodha_sell", sellPrice);
      else removeLocal("zerodha_sell");
      if (savePrefs.includes("qty")) setLocal("zerodha_qty", quantity);
      else removeLocal("zerodha_qty");
    }
  }, [
    savePref,
    savePrefs,
    currentTab,
    tradeType,
    buyPrice,
    sellPrice,
    quantity,
  ]);

  // --- Calculations (React way) ---
  const easyResult = useMemo(() => {
    let charges = 0,
      breakdown = {};
    if (investmentType === "equity_delivery") {
      breakdown.brokerage = 0;
      breakdown.stt = 0.001 * amount;
      breakdown.txn = 0.0000345 * 2 * amount;
      breakdown.sebi = 0.000001 * 2 * amount;
      breakdown.gst = 0.18 * (breakdown.txn + breakdown.sebi);
      breakdown.stamp = 0.00015 * amount;
      breakdown.dp = 13.5;
      charges =
        breakdown.brokerage +
        breakdown.stt +
        breakdown.txn +
        breakdown.sebi +
        breakdown.gst +
        breakdown.stamp +
        breakdown.dp;
    } else if (investmentType === "equity_intraday") {
      breakdown.brokerage = Math.min(0.0003 * amount, 20) * 2;
      breakdown.stt = 0.00025 * amount;
      breakdown.txn = 0.0000345 * 2 * amount;
      breakdown.sebi = 0.000001 * 2 * amount;
      breakdown.gst =
        0.18 * (breakdown.brokerage + breakdown.txn + breakdown.sebi);
      breakdown.stamp = 0.00003 * amount;
      breakdown.dp = 0;
      charges =
        breakdown.brokerage +
        breakdown.stt +
        breakdown.txn +
        breakdown.sebi +
        breakdown.gst +
        breakdown.stamp;
    } else if (investmentType === "mutual_fund") {
      breakdown.brokerage = 0;
      breakdown.stt = 0.00005 * amount;
      breakdown.txn = 0.00001 * amount;
      breakdown.gst = 0.01 * amount;
      breakdown.other = 6.49;
      charges = breakdown.stt + breakdown.txn + breakdown.gst + breakdown.other;
    } else if (investmentType === "etf") {
      breakdown.brokerage = 0;
      breakdown.stt = 0.001 * amount;
      breakdown.txn = 0.0000345 * 2 * amount;
      breakdown.sebi = 0.000001 * 2 * amount;
      breakdown.gst = 0.18 * (breakdown.txn + breakdown.sebi);
      breakdown.stamp = 0.00015 * amount;
      breakdown.dp = 13.5;
      charges =
        breakdown.brokerage +
        breakdown.stt +
        breakdown.txn +
        breakdown.sebi +
        breakdown.gst +
        breakdown.stamp +
        breakdown.dp;
    }
    const breakEven = amount + charges;
    const gainPercent = (charges / amount) * 100;
    return {
      breakEven,
      gainPercent,
      breakdown,
      charges,
      type: investmentType,
      amount,
    };
  }, [investmentType, amount]);

  const accurateResult = useMemo(() => {
    let brokerage = 0,
      stt = 0,
      txn = 0,
      sebi = 0,
      gst = 0,
      stamp = 0,
      dp = 0,
      totalCharges = 0;
    let breakdown = {};
    const amountVal = buyPrice * quantity;
    const sellAmount = sellPrice * quantity;
    if (tradeType === "equity_delivery") {
      brokerage = 0;
      stt = 0.001 * sellAmount;
      txn = 0.0000345 * (amountVal + sellAmount);
      sebi = 0.000001 * (amountVal + sellAmount);
      gst = 0.18 * (txn + sebi);
      stamp = 0.00015 * amountVal;
      dp = 13.5;
      totalCharges = brokerage + stt + txn + sebi + gst + stamp + dp;
      breakdown = { brokerage, stt, txn, sebi, gst, stamp, dp };
    } else if (tradeType === "equity_intraday") {
      brokerage = Math.min(0.0003 * amountVal, 20) * 2;
      stt = 0.00025 * sellAmount;
      txn = 0.0000345 * (amountVal + sellAmount);
      sebi = 0.000001 * (amountVal + sellAmount);
      gst = 0.18 * (brokerage + txn + sebi);
      stamp = 0.00003 * amountVal;
      dp = 0;
      totalCharges = brokerage + stt + txn + sebi + gst + stamp;
      breakdown = { brokerage, stt, txn, sebi, gst, stamp };
    }
    const netProfit = sellAmount - amountVal - totalCharges;
    return {
      totalCharges,
      netProfit,
      breakdown,
      tradeType,
      amount: amountVal,
      sellAmount,
      qty: quantity,
    };
  }, [tradeType, buyPrice, sellPrice, quantity]);

  // --- Save Pref Handlers ---
  function handleSavePrefToggle() {
    setSavePref((prev) => !prev);
    setTimeout(() => setSavePrefStatus("Preference will be saved!"), 100);
    setTimeout(() => setSavePrefStatus(""), 2200);
    if (!savePref) {
      setSavePrefs([]);
    }
  }
  function handleSavePrefOptionChange(option) {
    setSavePrefs((prev) =>
      prev.includes(option)
        ? prev.filter((o) => o !== option)
        : [...prev, option]
    );
  }

  // --- Tab/TradeType Handlers ---
  function handleTabSwitch(tab) {
    if (tab === currentTab) return;
    setCurrentTab(tab);
    setShowEasyBreakdown(false);
    setShowAccurateBreakdown(false);
  }
  function handleTradeType(type) {
    setTradeType(type);
    setShowAccurateBreakdown(false);
  }

  // --- Easy/Accurate Breakdown Toggles ---
  function handleToggleEasyBreakdown() {
    setShowEasyBreakdown((prev) => !prev);
  }
  function handleToggleAccurateBreakdown() {
    setShowAccurateBreakdown((prev) => !prev);
  }

  // --- Render breakdowns ---
  function renderEasyBreakdown(data) {
    const { type, breakdown, charges } = data;
    let rows = [];
    if (type === "equity_delivery" || type === "etf") {
      rows.push(["Brokerage", breakdown.brokerage]);
      rows.push(["STT", breakdown.stt]);
      rows.push(["Transaction Charges", breakdown.txn]);
      rows.push(["SEBI Charges", breakdown.sebi]);
      rows.push(["GST", breakdown.gst]);
      rows.push(["Stamp Duty", breakdown.stamp]);
      rows.push(["DP Charges", breakdown.dp]);
    } else if (type === "equity_intraday") {
      rows.push(["Brokerage", breakdown.brokerage]);
      rows.push(["STT", breakdown.stt]);
      rows.push(["Transaction Charges", breakdown.txn]);
      rows.push(["SEBI Charges", breakdown.sebi]);
      rows.push(["GST", breakdown.gst]);
      rows.push(["Stamp Duty", breakdown.stamp]);
    } else if (type === "mutual_fund") {
      rows.push(["STT", breakdown.stt]);
      rows.push(["Transaction Charges", breakdown.txn]);
      rows.push(["GST", breakdown.gst]);
      rows.push(["Other", breakdown.other]);
    }
    rows.push(["Total Charges", charges]);
    return (
      <table className="brokerage-table">
        <tbody>
          {rows.map(([label, value], i) => (
            <tr key={label}>
              <td className="charge-label">{label}</td>
              <td className="charge-value">₹{value.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    );
  }
  function renderAccurateBreakdown(data) {
    const { tradeType, breakdown, totalCharges } = data;
    let rows = [];
    if (tradeType === "equity_delivery") {
      rows.push(["Brokerage", breakdown.brokerage]);
      rows.push(["STT", breakdown.stt]);
      rows.push(["Transaction Charges", breakdown.txn]);
      rows.push(["SEBI Charges", breakdown.sebi]);
      rows.push(["GST", breakdown.gst]);
      rows.push(["Stamp Duty", breakdown.stamp]);
      rows.push(["DP Charges", breakdown.dp]);
    } else if (tradeType === "equity_intraday") {
      rows.push(["Brokerage", breakdown.brokerage]);
      rows.push(["STT", breakdown.stt]);
      rows.push(["Transaction Charges", breakdown.txn]);
      rows.push(["SEBI Charges", breakdown.sebi]);
      rows.push(["GST", breakdown.gst]);
      rows.push(["Stamp Duty", breakdown.stamp]);
    }
    rows.push(["Total Charges", totalCharges]);
    return (
      <table className="brokerage-table">
        <tbody>
          {rows.map(([label, value], i) => (
            <tr key={label}>
              <td className="charge-label">{label}</td>
              <td className="charge-value">₹{value.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  // --- UI ---
  return (
    <>
      <style>{style}</style>
      <div className="brokerage-container">
        <h2>
          <i className="fa-solid fa-calculator"></i>Brokerage Calculator
        </h2>
        <div className="brokerage-tabs">
          <div
            className={`brokerage-tab${currentTab === "easy" ? " active" : ""}`}
            onClick={() => handleTabSwitch("easy")}
          >
            <i className="fa-solid fa-bolt"></i> Easy
          </div>
          <div
            className={`brokerage-tab${currentTab === "accurate" ? " active" : ""}`}
            onClick={() => handleTabSwitch("accurate")}
          >
            <i className="fa-solid fa-sliders"></i> Accurate
          </div>
        </div>
        {/* Easy Tab */}
        {currentTab === "easy" && (
          <div className="brokerage-tab-content">
            <div className="accurate-row">
              <div className="accurate-flex-row">
                <div className="accurate-col">
                  <label htmlFor="investmentType">
                    <i className="fa-solid fa-layer-group"></i> Select
                    Investment Type:
                  </label>
                  <select
                    id="investmentType"
                    value={investmentType}
                    onChange={(e) => setInvestmentType(e.target.value)}
                  >
                    <option value="equity_delivery">Equity Delivery</option>
                    <option value="equity_intraday">Equity Intraday</option>
                    <option value="mutual_fund">Mutual Fund</option>
                    <option value="etf">ETF</option>
                  </select>
                </div>
                <div className="accurate-col">
                  <label htmlFor="amount">
                    <i className="fa-solid fa-indian-rupee-sign"></i> Enter
                    Amount (₹):
                  </label>
                  <input
                    type="number"
                    id="amount"
                    value={amount}
                    onChange={(e) => setAmount(Number(e.target.value))}
                  />
                </div>
              </div>
              <div className="preset-buttons" style={{ marginBottom: 8 }}>
                {[10000, 20000, 100000, 200000, 500000].map((val) => (
                  <button
                    key={val}
                    type="button"
                    onClick={() => setAmount(val)}
                  >
                    <i className="fa-solid fa-coins"></i> ₹
                    {val >= 100000 ? val / 100000 + "L" : val / 1000 + "K"}
                  </button>
                ))}
              </div>
              <button
                type="button"
                onClick={() => setShowEasyBreakdown(false)}
                style={{ width: "100%", marginTop: 8 }}
              >
                <i className="fa-solid fa-calculator"></i> Calculate
              </button>
              <div className="result" id="resultEasy">
                {easyResult && (
                  <>
                    <i className="fa-solid fa-arrow-trend-up"></i> Break-even
                    Sell Price:{" "}
                    <span style={{ color: "var(--primary-dark)" }}>
                      ₹{easyResult.breakEven.toFixed(2)}
                    </span>
                    <br />
                    <i className="fa-solid fa-percent"></i> Required Gain:{" "}
                    <span style={{ color: "var(--primary)" }}>
                      {easyResult.gainPercent.toFixed(2)}%
                    </span>
                  </>
                )}
              </div>
              {easyResult && (
                <>
                  <button
                    type="button"
                    onClick={handleToggleEasyBreakdown}
                    style={{ width: "100%", marginTop: 8, display: "block" }}
                  >
                    <i
                      className={`fa-solid fa-angle-${
                        showEasyBreakdown ? "up" : "down"
                      }`}
                    ></i>{" "}
                    {showEasyBreakdown ? "Hide" : "Show"} Charges Breakdown
                  </button>
                  <div
                    className="breakdown-section"
                    style={{ display: showEasyBreakdown ? "block" : "none" }}
                  >
                    {renderEasyBreakdown(easyResult)}
                  </div>
                </>
              )}
            </div>
          </div>
        )}
        {/* Accurate Tab */}
        {currentTab === "accurate" && (
          <div className="brokerage-tab-content">
            <div className="accurate-row">
              <div className="centered-row">
                <div
                  className={`segmented-control${tradeType === 'equity_intraday' ? ' intraday' : ''}`}
                  id="tradeTypeSegmented"
                  style={{
                    border: `1.5px solid ${tradeType === 'equity_intraday' ? '#64c1ffd8' : '#2980b9'}`,
                  }}
                >
                  <div
                    className="segmented-active-bg"
                    style={{
                      left: tradeType === 'equity_intraday' ? '50%' : 0,
                      background: tradeType === 'equity_intraday' ? '#64c1ffd8' : '#2980b9',
                      boxShadow: `0 0 8px 2px ${tradeType === 'equity_intraday' ? '#2980b9' : '#64c1ffd8'}`,
                      position: 'absolute',
                      top: 0,
                      width: '50%',
                      height: '100%',
                      borderRadius: 8,
                      zIndex: 1,
                      transition: 'left 0.32s cubic-bezier(.77,0,.18,1), background 0.2s',
                    }}
                  />
                  <button
                    type="button"
                    className={`segmented-btn${tradeType === 'equity_delivery' ? ' active' : ''}`}
                    onClick={() => handleTradeType('equity_delivery')}
                    style={{
                      color: tradeType === 'equity_delivery' ? '#fff' : '#64c1ffd8',
                      fontWeight: tradeType === 'equity_delivery' ? 'bold' : '500',
                      textShadow: tradeType === 'equity_delivery' ? '0 1px 4px rgba(0,0,0,0.25)' : 'none',
                      zIndex: 2,
                      background: 'transparent',
                    }}
                  >
                    <i className="fa-solid fa-box"></i> Delivery
                  </button>
                  <button
                    type="button"
                    className={`segmented-btn${tradeType === 'equity_intraday' ? ' active' : ''}`}
                    onClick={() => handleTradeType('equity_intraday')}
                    style={{
                      color: tradeType === 'equity_intraday' ? '#fff' : '#2980b9',
                      fontWeight: tradeType === 'equity_intraday' ? 'bold' : '500',
                      textShadow: tradeType === 'equity_intraday' ? '0 1px 4px rgba(0,0,0,0.25)' : 'none',
                      zIndex: 2,
                      background: 'transparent',
                    }}
                  >
                    <i className="fa-solid fa-bolt"></i> Intraday
                  </button>
                </div>
                <input
                  type="hidden"
                  id="tradeType"
                  value={tradeType}
                  readOnly
                />
              </div>
              <div className="save-pref-block">
                <div
                  className="save-pref-row"
                  style={{ position: "relative" }}
                >
                  <span className="save-pref-label">Save preference</span>
                  <span
                    className="save-pref-tooltip-icon"
                    tabIndex={0}
                    onClick={() => setShowSavePrefTooltip((v) => !v)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter")
                        setShowSavePrefTooltip((v) => !v);
                    }}
                  >
                    <i className="fa-solid fa-circle-info"></i>
                  </span>
                  <span
                    className={`save-pref-tooltip${
                      showSavePrefTooltip ? " show" : ""
                    }`}
                    id="savePrefTooltip"
                  >
                    When enabled, your selected tab and trade type will be
                    remembered for your next visit. Turn off to forget your
                    choices.
                  </span>
                </div>
                <div
                  style={{ display: "flex", alignItems: "center", gap: 10 }}
                >
                  <span
                    className={`save-pref-toggle${savePref ? " active" : ""}`}
                    id="savePrefToggle"
                    tabIndex={0}
                    onClick={handleSavePrefToggle}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") handleSavePrefToggle();
                    }}
                  >
                    <span className="save-pref-toggle-knob">
                      <span className="save-pref-toggle-icon">
                        <i className="fa-solid fa-star"></i>
                      </span>
                    </span>
                  </span>
                  <div
                    className="multi-select-dropdown"
                    id="savePrefOptionsDropdown"
                  >
                    <div
                      className="multi-select-selected"
                      onClick={() => setShowSavePrefOptions((v) => !v)}
                      tabIndex={0}
                      onKeyDown={(e) => {
                        if (e.key === "Enter")
                          setShowSavePrefOptions((v) => !v);
                      }}
                    >
                      <span id="savePrefSelectedText">Options</span>
                      <i className="fa-solid fa-caret-down"></i>
                    </div>
                    <div
                      className="multi-select-options"
                      id="savePrefOptionsList"
                      style={{
                        display: showSavePrefOptions ? "flex" : "none",
                      }}
                    >
                      {["tab", "tradeType", "buy", "sell", "qty"].map(
                        (opt) => (
                          <label key={opt}>
                            <input
                              type="checkbox"
                              value={opt}
                              checked={savePrefs.includes(opt)}
                              onChange={() => handleSavePrefOptionChange(opt)}
                            />{" "}
                            {opt.charAt(0).toUpperCase() +
                              opt
                                .slice(1)
                                .replace("Type", " Type")
                                .replace("qty", "Quantity")}
                          </label>
                        )
                      )}
                    </div>
                  </div>
                </div>
                <input
                  type="checkbox"
                  id="savePrefCheck"
                  style={{ display: "none" }}
                  checked={savePref}
                  readOnly
                />
                <span
                  className={`save-pref-status${
                    savePrefStatus ? " active" : ""
                  }`}
                  id="savePrefStatus"
                >
                  {savePrefStatus}
                </span>
              </div>
            </div>
            <div className="accurate-flex-row">
              <div className="accurate-col">
                <label htmlFor="buyPrice">
                  <i className="fa-solid fa-arrow-up"></i> Buy Price (₹):
                </label>
                <input
                  type="number"
                  id="buyPrice"
                  value={buyPrice}
                  onChange={(e) => setBuyPrice(Number(e.target.value))}
                />
              </div>
              <div className="accurate-col">
                <label htmlFor="sellPrice">
                  <i className="fa-solid fa-arrow-down"></i> Sell Price (₹):
                </label>
                <input
                  type="number"
                  id="sellPrice"
                  value={sellPrice}
                  onChange={(e) => setSellPrice(Number(e.target.value))}
                />
              </div>
            </div>
            <div className="accurate-row">
              <label htmlFor="quantity">
                <i className="fa-solid fa-hashtag"></i> Quantity:
              </label>
              <input
                type="number"
                id="quantity"
                value={quantity}
                onChange={(e) => setQuantity(Number(e.target.value))}
              />
            </div>
            <div className="accurate-row">
              <button
                type="button"
                onClick={() => setShowAccurateBreakdown(false)}
              >
                <i className="fa-solid fa-calculator"></i> Calculate
              </button>
              <div className="result" id="resultAccurate">
                {accurateResult && (
                  <>
                    <i className="fa-solid fa-receipt"></i> Total Charges:{" "}
                    <span style={{ color: "var(--primary-dark)" }}>
                      ₹{accurateResult.totalCharges.toFixed(2)}
                    </span>
                    <br />
                    Net{" "}
                    {accurateResult.netProfit >= 0 ? (
                      <span className="positive">
                        <i className="fa-solid fa-arrow-up"></i> Profit
                      </span>
                    ) : (
                      <span className="negative">
                        <i className="fa-solid fa-arrow-down"></i> Loss
                      </span>
                    )}
                    :{" "}
                    <span
                      style={{
                        color:
                          accurateResult.netProfit >= 0 ? "#27ae60" : "#e74c3c",
                      }}
                    >
                      ₹{accurateResult.netProfit.toFixed(2)}
                    </span>
                  </>
                )}
              </div>
              {accurateResult && (
                <>
                  <button
                    type="button"
                    onClick={handleToggleAccurateBreakdown}
                    style={{ width: "100%", marginTop: 8, display: "block" }}
                  >
                    <i
                      className={`fa-solid fa-angle-${
                        showAccurateBreakdown ? "up" : "down"
                      }`}
                    ></i>{" "}
                    {showAccurateBreakdown ? "Hide" : "Show"} Charges Breakdown
                  </button>
                  <div
                    className="breakdown-section"
                    style={{
                      display: showAccurateBreakdown ? "block" : "none",
                    }}
                  >
                    {renderAccurateBreakdown(accurateResult)}
                  </div>
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </>
  );
}

export default BrokerageTab;
