        id: 'vwap',
        label: 'VWAP',
        type: 'line',
        data: vwapData.filter(d => d.y !== null),
        yAxisID: 'priceAxis',
        borderColor: '#a259f7', // purple
        backgroundColor: 'rgba(0,0,0,0)',
