        setShowVolumeProfile(settings.showVolumeProfile || false);
        setShowMovingAverage(settings.showMovingAverage || false);
        setMaPeriod(settings.maPeriod || 20);
        setMaType(settings.maType || 'SMA');
        setShowBollingerBands(settings.showBollingerBands || false);
        setBbPeriod(settings.bbPeriod || 20);
        setBbStdDev(settings.bbStdDev || 2);
        setShowVWAP(settings.showVWAP || false);
        setShowStochastic(settings.showStochastic || false);
        setStochKPeriod(settings.stochKPeriod || 14);
        setStochDPeriod(settings.stochDPeriod || 3);
        setStochSmooth(settings.stochSmooth || 3);
        setShowLegend(settings.showLegend !== undefined ? settings.showLegend : true);
