  // Add state for crosshair tooltip position and data
  const [crosshairTooltip, setCrosshairTooltip] = useState(null); // {x, y, candle}

  // Helper: find nearest candle to a pixel x position
  function getNearestCandle(px) {
    if (!chartInstance.current || !candlesRef.current.length) return null;
    const chart = chartInstance.current;
    const xScale = chart.scales.x;
    // Convert pixel to data x
    const dataX = xScale.getValueForPixel(px);
    // Find nearest candle by x
    let minDist = Infinity, nearest = null;
    for (const candle of candlesRef.current) {
      const dist = Math.abs(candle.x - dataX);
      if (dist < minDist) {
        minDist = dist;
        nearest = candle;
      }
    }
    return nearest;
  }

  // Handler: on chart click, set tooltip at that point
